package com.configmonitor.app;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class FeaturesTest {
 JSONObject node(int failures,boolean latency)throws Exception{return Parser.j("rules",Rules.validate(Parser.j("failureLimit",failures,"latencyEnabled",latency,"latencyMs",700,"latencyStreak",3)));}
 @Test public void sixthFailureAndRecovery()throws Exception{JSONObject n=node(6,false);for(int i=0;i<5;i++)assertFalse(Rules.apply(n,false,-1,1));assertTrue(Rules.apply(n,false,-1,1));assertFalse(Rules.apply(n,false,-1,1));Rules.acknowledge(n);for(int i=0;i<5;i++)assertFalse(Rules.apply(n,false,-1,1));assertTrue(Rules.apply(n,false,-1,1));Rules.apply(n,true,100,2);for(int i=0;i<5;i++)assertFalse(Rules.apply(n,false,-1,3));assertTrue(Rules.apply(n,false,-1,3));}
 @Test public void latencyRequiresConsecutiveSlowSuccesses()throws Exception{JSONObject n=node(6,true);assertFalse(Rules.apply(n,true,701,1));assertFalse(Rules.apply(n,true,800,2));Rules.apply(n,true,100,3);assertFalse(Rules.apply(n,true,800,4));assertFalse(Rules.apply(n,true,800,5));assertTrue(Rules.apply(n,true,800,6));assertEquals("latency",n.getString("incidentReason"));assertFalse(Rules.apply(n,true,800,7));}
 @Test public void suppressionCollectsDataAndRearmsOnFreshResult()throws Exception{JSONObject n=node(2,false).put("maintenanceUntil",100);assertFalse(Rules.apply(n,false,-1,1));assertFalse(Rules.apply(n,false,-1,2));assertEquals(2,n.getInt("failures"));assertTrue(Rules.apply(n,false,-1,101));n.put("snoozeUntil",200).put("alerted",false).put("ack",false);assertFalse(Rules.apply(n,false,-1,150));assertTrue(Rules.apply(n,false,-1,201));}
 @Test public void recoveryDuringSnoozePreventsStaleAlarm()throws Exception{JSONObject n=node(1,false).put("snoozeUntil",100);assertFalse(Rules.apply(n,false,-1,1));assertFalse(Rules.apply(n,true,90,2));assertFalse(Rules.apply(n,true,90,101));}
 @Test public void customThresholdAndDisabledLatency()throws Exception{JSONObject n=node(2,false);for(int i=0;i<10;i++)assertFalse(Rules.apply(n,true,5000,i));assertFalse(Rules.apply(n,false,-1,20));assertTrue(Rules.apply(n,false,-1,21));}
 @Test public void fallbackStopsAtFirstSuccess()throws Exception{int[] calls={0};Engine.Result r=Engine.runTargets(new JSONArray("[\"https://a.test\",\"https://b.test\",\"https://c.test\"]"),u->{calls[0]++;return new Engine.Result(calls[0]==2,123,"timeout");});assertTrue(r.ok);assertEquals(2,calls[0]);assertEquals(2,r.attempts.length());}
 @Test public void failedFallbackCycleIsOneFailure()throws Exception{Engine.Result r=Engine.runTargets(new JSONArray("[\"https://a.test\",\"https://b.test\"]"),u->new Engine.Result(false,-1,"timeout"));JSONObject n=node(6,false);Rules.apply(n,r.ok,r.ms,1);assertFalse(r.ok);assertEquals(1,n.getInt("failures"));assertEquals(2,r.attempts.length());assertEquals("unknown",r.attempts.getJSONObject(0).getString("stage"));}
 @Test public void durationsSplitAndDoNotFillGaps(){List<long[]> s=Observation.slices(3590000,3630000,20);assertEquals(2,s.size());assertArrayEquals(new long[]{0,10000},s.get(0));assertArrayEquals(new long[]{3600000,30000},s.get(1));long sum=0;for(long[] x:Observation.slices(1000,1000000,20))sum+=x[1];assertEquals(40000,sum);assertTrue(Observation.slices(500,499,20).isEmpty());assertTrue(Observation.slices(0,500,20).isEmpty());}
 @Test public void targetValidation()throws Exception{assertEquals("https://example.com",Targets.validate(new JSONArray().put("example.com")).getString(0));for(String u:new String[]{"https://u:p@example.com","https://example.com/#fragment","file:///tmp/a","https://example.com/\r\nx"}){try{Targets.validate(new JSONArray().put(u));fail(u);}catch(Exception expected){}}}
 @Test public void zeroThresholdRejected()throws Exception{try{Rules.validate(Parser.j("failureLimit",0));fail();}catch(IllegalArgumentException expected){}}
}
